// GinServerOptions provides options for the Gin server.
type GinServerOptions struct {
	BaseURL      string
	Middlewares  []MiddlewareFunc
	ErrorHandler func(*gin.Context, error, int)
}

// RegisterHandlers creates http.Handler with routing matching OpenAPI spec.
func RegisterHandlers(router gin.IRouter, si ServerInterface) {
	RegisterHandlersWithOptions(router, si, GinServerOptions{})
}

// RegisterHandlersWithOptions creates http.Handler with additional options
func RegisterHandlersWithOptions(router gin.IRouter, si ServerInterface, options GinServerOptions) {
	errorHandler := options.ErrorHandler
	if errorHandler == nil {
		errorHandler = func(c *gin.Context, err error, statusCode int) {
			c.JSON(statusCode, gin.H{"msg": err.Error()})
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandler:       errorHandler,
	}

	router.GET(options.BaseURL+"/v1/health", wrapper.GetHealth)
	router.GET(options.BaseURL+"/v1/metadata", wrapper.GetMetadata)
	router.POST(options.BaseURL+"/v1/sessions", wrapper.OpenSession)
	router.DELETE(options.BaseURL+"/v1/sessions/:id", wrapper.CloseSession)
	router.GET(options.BaseURL+"/v1/sessions/:id", wrapper.GetSession)
	router.GET(options.BaseURL+"/v1/sessions/:id/events", wrapper.GetSessionEvents)
	router.GET(options.BaseURL+"/v1/channels/:channel", wrapper.GetChannel)
	router.POST(options.BaseURL+"/v1/channels/:channel/vouchers", wrapper.SendChannelVoucher)
	router.POST(options.BaseURL+"/v1/leases/:lease/vouchers", wrapper.SendLeaseVoucher)
	router.GET(options.BaseURL+"/v1/leases/:lease", wrapper.GetLease)
	router.GET(options.BaseURL+"/v1/leases/:lease/events", wrapper.GetLeaseEvents)
}

